    Errors from resolving the project root or the project-local/global target
    directories are handled gracefully: if one category of lookups fails, the
    remaining categories are still checked. Only returns ``False`` (without
    raising) if no installed skill can be detected after all available lookups.
    """
    target_dirs: list[Path] = []

    # Resolve project-local target directories. If the project root cannot be
    # determined, still fall through to the global directories below.
    try:
        project_root = _find_project_root()
    except (OSError, RuntimeError):
        project_root = None

    if project_root is not None:
        # Even if collecting the project target dirs fails, still check globals.
        try:
            target_dirs.extend(_get_project_target_dirs(project_root))
        except (OSError, RuntimeError):
            pass

    # Resolve global target directories. If this fails, the project-local
    # directories collected above are still evaluated below.
    try:
        target_dirs.extend(_get_global_target_dirs())
    except (OSError, RuntimeError):
        pass

    for target_dir in target_dirs:
        skill_path = target_dir / _GLOBAL_SKILL_NAME
        try:
            if skill_path.is_dir() or skill_path.is_symlink():
                return True
        except (OSError, RuntimeError):
            continue

    return False


